import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable, tap } from 'rxjs';
import { SessionStorageService } from './session-storage.service';
import { LoginPayload, RegisterPayload } from '@app/models/user.model';
import { Router } from '@angular/router';

const API_URL = "http://localhost:4000";

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  private isAuthorized$$ = new BehaviorSubject<boolean>(true);
  public isAuthorized$: Observable<boolean> = this.isAuthorized$$.asObservable();

  constructor(
    private http: HttpClient,
    private sessionStorage: SessionStorageService,
    private router: Router
  ) { }

  login(user: LoginPayload): Observable<any> {
    return this.http.post<any>(`${API_URL}/login`, user).pipe(
      tap((response) => {
        const raw = response?.result ?? response?.token ?? null;
        const token = raw ? String(raw).replace(/^Bearer\s+/i, '') : null;
        if (token) {
          this.sessionStorage.setToken(token);
          this.isAuthorized$$.next(true);
        }
      })
    );
  }

  logout(): Observable<any> {
    this.sessionStorage.deleteToken();
    this.isAuthorized.nefalse;
    this.router.navigate(['/login']);
  }

  register(user: RegisterPayload): Observable<{ token: string }> {
    return this.http.post<{ token: string }>(`${API_URL}/register`, user);
  }

  get isAuthorized(): boolean {
    return this.isAuthorized$$.value;
  }

  set isAuthorized(value: boolean) {
    this.isAuthorized$$.next(value);
  }

  getLoginUrl(): string {
    return '/login';
  }
}
